root = {k: yaml.compose(v) for k, v in src.items()}
def child(node, step):
    if isinstance(step, tuple):
        key, val = step
        for it in node.value:
            for kn, vn in it.value:
                if kn.value == key and vn.value == val: return it, it
        raise KeyError(step)
    for kn, vn in node.value:
        if kn.value == step: return kn, vn
    raise KeyError(step)
def span(v, path):
    node = root[v]; kn = None
