import subprocess, re
V1 = 'experiments/EXP-BINSTD-178742/specification.v1-frozen-64e8b013.yaml'
V2 = 'experiments/EXP-BINSTD-178742/specification.yaml'
print('diff_version:', subprocess.run(['diff','--version'],capture_output=True,text=True).stdout.splitlines()[0])
out = subprocess.run(['diff', V1, V2], capture_output=True, text=True).stdout.splitlines()
v2lines = open(V2).read().split('\n')
hdr = re.compile(r'^(\d+)(?:,(\d+))?([acd])(\d+)(?:,(\d+))?$')
hunks = []; cur = None
for ln in out:
    m = hdr.match(ln)
    if m:
        cur = {'h': ln, 'type': m.group(3), 'old': [], 'new': [],
               'v2_from': int(m.group(4)), 'v2_to': int(m.group(5) or m.group(4))}
        hunks.append(cur); continue
    if ln.startswith('< '): cur['old'].append(ln[2:])
    elif ln.startswith('> '): cur['new'].append(ln[2:])
MARK = re.compile(r'V2|v2_|_v2|version 2|version-2')
def enclosing_marker(h):
    # look at the hunk's own new lines, then up to 25 v2 lines above it, for a marker
    if any(MARK.search(x) for x in h['new']): return 'in-hunk'
    lo = max(0, h['v2_from'] - 26)
    ctx = v2lines[lo:h['v2_from'] - 1]
    for i in range(len(ctx) - 1, -1, -1):
        if MARK.search(ctx[i]): return 'context-line-%d' % (lo + i + 1)
    return 'NONE'
tot_old = sum(len(h['old']) for h in hunks); tot_new = sum(len(h['new']) for h in hunks)
print('hunks:', len(hunks), 'v1_lines_changed_or_removed:', tot_old, 'v2_lines_added_or_changed:', tot_new)
for h in hunks:
    mk = enclosing_marker(h)
    print('HUNK', h['h'], 'type', h['type'], 'old', len(h['old']), 'new', len(h['new']), 'marker', mk)
    if h['type'] in 'cd':
        for x in h['old'][:6]: print('   <', x[:170])
        for x in h['new'][:6]: print('   >', x[:170])
    else:
        print('   > first:', h['new'][0][:170])

